def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Remove duplicates and sort
    sorted_unique = sorted(set(nums))

    # Group consecutive numbers
    ranges = []
    start = sorted_unique[0]
    current = start

    for i in range(1, len(sorted_unique)):
        if sorted_unique[i] == current + 1:
            current = sorted_unique[i]
        else:
            # End of current run
            if current - start >= 2:  # 3 or more consecutive numbers
                ranges.append(f"{start}..{current}")
            else:
                # 1 or 2 numbers
                for j in range(start, current + 1):
                    ranges.append(str(j))
            start = sorted_unique[i]
            current = start

    # Handle the last run
    if current - start >= 2:
        ranges.append(f"{start}..{current}")
    else:
        for j in range(start, current + 1):
            ranges.append(str(j))

    return ",".join(ranges)
